// App members: disabled controls retain parent-tracked explanatory tooltips.
std::wstring modelIdentitySummary(const json& value){if(!value.is_object()||value.empty())return L"미기록";auto state=str(value,"state");if(state=="changed_during_generation")return L"생성 중 모델 변경 · 재사용 확인 필요";auto fingerprint=str(value,"fingerprint");if(state=="verified_files"&&fingerprint.size()==64&&fingerprint.find_first_not_of("0123456789abcdef")==std::string::npos)return L"모델 파일 확인됨 · 실행 환경 미확인\r\n모델 지문  ·  "+wide(fingerprint);if(state=="not_configured")return L"모델 파일 폴더 미설정";return L"모델 파일 미검증";}
std::wstring modelIdentityHint(){auto rows=capabilities.value("model_catalog",json::array());if(rows.is_array())for(auto& row:rows)if(row.is_object()&&str(row,"id")==modelId(store->settings))return L"서버 기본 구성\r\n"+modelIdentitySummary(row.value("model_identity",json::object()))+L"\r\n개별 모델 변경 시 실제 생성 결과의 기록을 확인하세요.";return L"모델 파일 검증 정보는 서버 연결 후 확인할 수 있습니다.";}
HWND modelTooltip=nullptr;std::map<HWND,std::wstring> modelHintTexts;
void updateModelHints(bool create=false){if(create){modelTooltip=CreateWindowExW(WS_EX_TOPMOST,TOOLTIPS_CLASSW,nullptr,WS_POPUP|TTS_ALWAYSTIP|TTS_NOPREFIX,0,0,0,0,hwnd,nullptr,GetModuleHandle(nullptr),nullptr);if(!modelTooltip)return;SendMessageW(modelTooltip,TTM_SETMAXTIPWIDTH,0,int(400*dpi));}
 if(!modelTooltip)return;for(auto& f:fields){bool locked=modelLocked(store->settings,f.key);if(!locked&&f.key!="workflow_profile")continue;if(locked&&IsWindowEnabled(f.hwnd))EnableWindow(f.hwnd,FALSE);auto& reason=modelHintTexts[f.hwnd];if(f.key=="workflow_profile")reason=modelIdentityHint();else if(reason.empty())reason=L"선택한 모델의 필수 설정이거나 지원하지 않는 항목입니다. 모델을 변경하면 수정할 수 있습니다.";TOOLINFOW item{sizeof item};item.hwnd=hwnd;item.uId=(UINT_PTR)f.hwnd;item.uFlags=TTF_SUBCLASS|(f.key=="workflow_profile"?TTF_IDISHWND:0);item.rect={LONG(f.rect.x*dpi),LONG(f.rect.y*dpi),LONG((f.rect.x+f.rect.w)*dpi),LONG((f.rect.y+f.rect.h)*dpi)};item.lpszText=reason.data();SendMessageW(modelTooltip,create?TTM_ADDTOOLW:TTM_NEWTOOLRECTW,0,(LPARAM)&item);if(!create)SendMessageW(modelTooltip,TTM_UPDATETIPTEXTW,0,(LPARAM)&item);}}
